function resolveWalls(t){for(let pass=0;pass<2;pass++){for(const w of walls){const qx=clamp(t.x,w.x,w.x+w.w),qy=clamp(t.y,w.y,w.y+w.h),dx=t.x-qx,dy=t.y-qy,ds=dx*dx+dy*dy;if(ds>=t.r*t.r)continue;if(ds>.000001){const d=Math.sqrt(ds),push=t.r-d+.002;t.x+=dx/d*push;t.y+=dy/d*push;}else{const p=[{v:t.x-w.x,dx:-1,dy:0},{v:w.x+w.w-t.x,dx:1,dy:0},{v:t.y-w.y,dx:0,dy:-1},{v:w.y+w.h-t.y,dx:0,dy:1}].sort((a,b)=>a.v-b.v)[0];t.x+=p.dx*(p.v+t.r+.002);t.y+=p.dy*(p.v+t.r+.002);}}}}